import { PUBLIC_ROLE } from "@camis/permissions";

/**
 * A guest's grants are the public role's. Spatie keeps every permission with its roles in its
 * cache, so a guest's check reads no table once that cache is warm, as a user's does.
 */
export const emitPublicRole = (): string => `<?php
// @camis:generated — do not edit; regenerated by camis

declare(strict_types=1);

namespace App\\Support;

use Illuminate\\Contracts\\Auth\\Authenticatable;
use Spatie\\Permission\\PermissionRegistrar;

final class PublicRole
{
    /** Whether $user (null: a caller without a session) holds $permission. */
    public static function allows(?Authenticatable $user, string $permission): bool
    {
        if ($user !== null) {
            return $user->can($permission);
        }
        $found = app(PermissionRegistrar::class)->getPermissions(['name' => $permission])->first();

        return $found !== null && $found->roles->contains('name', '${PUBLIC_ROLE}');
    }
}
`;
